namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(e =>
        {
            e.HasIndex(s => s.TrackingNumber).IsUnique();
        });

        // Seed sample shipments
        builder.Entity<Shipment>().HasData(
            new Shipment { Id = 1, TrackingNumber = "TRK-20260701-001", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, CreatedAt = new DateTime(2026, 7, 1, 10, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2026, 7, 18, 14, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 2, TrackingNumber = "TRK-20260702-002", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = ShipmentStatus.PickedUp, CreatedAt = new DateTime(2026, 7, 2, 8, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2026, 7, 22, 12, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 3, TrackingNumber = "TRK-20260703-003", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = ShipmentStatus.OutForDelivery, CreatedAt = new DateTime(2026, 7, 3, 6, 30, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2026, 7, 15, 9, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 4, TrackingNumber = "TRK-20260704-004", Origin = "Sydney, Australia", Destination = "São Paulo, Brazil", Status = ShipmentStatus.Pending, CreatedAt = new DateTime(2026, 7, 4, 14, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2026, 7, 25, 16, 0, 0, DateTimeKind.Utc) },
            new Shipment { Id = 5, TrackingNumber = "TRK-20260705-005", Origin = "Mumbai, India", Destination = "Dubai, UAE", Status = ShipmentStatus.Delivered, CreatedAt = new DateTime(2026, 7, 5, 11, 0, 0, DateTimeKind.Utc), EstimatedDelivery = new DateTime(2026, 7, 10, 10, 0, 0, DateTimeKind.Utc) }
        );
    }
}

