using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;

namespace ShipmentTracker;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // Get all shipments (dispatchers)
        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new
                {
                    s.Id,
                    s.TrackingNumber,
                    s.Origin,
                    s.Destination,
                    Status = s.Status.ToString(),
                    s.CreatedAt,
                    s.EstimatedDelivery,
                    s.Notes,
                    s.CustomerId
                })
                .ToListAsync();
            return Results.Ok(shipments);
        });

        // Track a shipment by tracking number (customers)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .Where(s => s.TrackingNumber == trackingNumber)
                .Select(s => new
                {
                    s.Id,
                    s.TrackingNumber,
                    s.Origin,
                    s.Destination,
                    Status = s.Status.ToString(),
                    s.CreatedAt,
                    s.EstimatedDelivery,
                    s.Notes
                })
                .FirstOrDefaultAsync();

            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        // Create a shipment (dispatchers)
        group.MapPost("/", async (CreateShipmentRequest request, ApplicationDbContext db) =>
        {
            var shipment = new Shipment
            {
                TrackingNumber = request.TrackingNumber,
                Origin = request.Origin,
                Destination = request.Destination,
                Status = ShipmentStatus.Pending,
                CreatedAt = DateTime.UtcNow,
                EstimatedDelivery = request.EstimatedDelivery,
                Notes = request.Notes,
                CustomerId = request.CustomerId
            };
            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", new
            {
                shipment.Id,
                shipment.TrackingNumber,
                shipment.Origin,
                shipment.Destination,
                Status = shipment.Status.ToString(),
                shipment.CreatedAt,
                shipment.EstimatedDelivery,
                shipment.Notes,
                shipment.CustomerId
            });
        });

        // Update shipment status (dispatchers)
        group.MapPut("/{id:int}/status", async (int id, UpdateStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            if (Enum.TryParse<ShipmentStatus>(request.Status, true, out var status))
            {
                shipment.Status = status;
                shipment.Notes = request.Notes ?? shipment.Notes;
                await db.SaveChangesAsync();
                return Results.Ok(new
                {
                    shipment.Id,
                    shipment.TrackingNumber,
                    Status = shipment.Status.ToString(),
                    shipment.Notes
                });
            }
            return Results.BadRequest("Invalid status value.");
        });
    }
}

public record CreateShipmentRequest(
    string TrackingNumber,
    string Origin,
    string Destination,
    DateTime? EstimatedDelivery,
    string? Notes,
    string? CustomerId);

public record UpdateStatusRequest(string Status, string? Notes);

