+@page "/dispatcher"
+@using Microsoft.AspNetCore.Authorization
+@using ShipmentTracker.Client.Models
+@attribute [Authorize]
+@rendermode InteractiveWebAssembly
+
+<PageTitle>Dispatcher Dashboard</PageTitle>
+
+<h3>Dispatcher Dashboard</h3>
+
+<div class="mb-3 d-flex gap-2">
+    <input class="form-control" style="max-width:300px" placeholder="Filter by destination..."
+           @bind="filterText" @bind:event="oninput" />
+    <select class="form-select" style="max-width:200px" @bind="statusFilter">
+        <option value="">All Statuses</option>
+        <option value="Pending">Pending</option>
+        <option value="PickedUp">Picked Up</option>
+        <option value="InTransit">In Transit</option>
+        <option value="OutForDelivery">Out for Delivery</option>
+        <option value="Delivered">Delivered</option>
+        <option value="Exception">Exception</option>
+    </select>
+    <button class="btn btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
+</div>
+
+@if (showCreate)
+{
+    <div class="card mb-3 p-3">
+        <h5>Create Shipment</h5>
+        <div class="row g-2">
+            <div class="col-md-3">
+                <input class="form-control" placeholder="Tracking #" @bind="newTrackingNumber" />
+            </div>
+            <div class="col-md-3">
+                <input class="form-control" placeholder="Origin" @bind="newOrigin" />
+            </div>
+            <div class="col-md-3">
+                <input class="form-control" placeholder="Destination" @bind="newDestination" />
+            </div>
+            <div class="col-md-3">
+                <input type="date" class="form-control" @bind="newEstimatedDelivery" />
+            </div>
+        </div>
+        <div class="mt-2">
+            <button class="btn btn-success btn-sm" @onclick="CreateShipment" disabled="@isCreating">Create</button>
+            <button class="btn btn-secondary btn-sm" @onclick="() => showCreate = false">Cancel</button>
+        </div>
+        @if (!string.IsNullOrEmpty(createError))
+        {
+            <div class="text-danger mt-1">@createError</div>
+        }
+    </div>
+}
+
+@if (shipments == null)
+{
+    <p><em>Loading shipments...</em></p>
+}
+else if (!FilteredShipments.Any())
+{
+    <p>No shipments match the current filter.</p>
+}
+else
+{
+    <div class="table-responsive">
+        <table class="table table-striped table-hover">
+            <thead>
+                <tr>
+                    <th>Tracking #</th>
+                    <th>Origin</th>
+                    <th>Destination</th>
+                    <th>Status</th>
+                    <th>Created</th>
+                    <th>Est. Delivery</th>
+                    <th>Actions</th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var s in FilteredShipments)
+                {
+                    <tr>
+                        <td><code>@s.TrackingNumber</code></td>
+                        <td>@s.Origin</td>
+                        <td>@s.Destination</td>
+                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@FormatStatus(s.Status)</span></td>
+                        <td>@s.CreatedAt.ToString("yyyy-MM-dd")</td>
+                        <td>@(s.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</td>
+                        <td>
+                            <select class="form-select form-select-sm" style="width:auto;display:inline-block"
+                                    value="@s.Status" @onchange="e => UpdateStatus(s, e.Value?.ToString())">
+                                <option value="Pending">Pending</option>
+                                <option value="PickedUp">Picked Up</option>
+                                <option value="InTransit">In Transit</option>
+                                <option value="OutForDelivery">Out for Delivery</option>
+                                <option value="Delivered">Delivered</option>
+                                <option value="Exception">Exception</option>
+                            </select>
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+}
+
+@code {
+    [Inject] private HttpClient Http { get; set; } = default!;
+
+    private List<ShipmentDto>? shipments;
+    private string filterText = "";
+    private string statusFilter = "";
+    private bool showCreate;
+    private bool isCreating;
+    private string? createError;
+
+    private string newTrackingNumber = "";
+    private string newOrigin = "";
+    private string newDestination = "";
+    private DateTime? newEstimatedDelivery;
+
+    private IEnumerable<ShipmentDto> FilteredShipments => shipments?
+        .Where(s => (string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)))
+        .Where(s => (string.IsNullOrEmpty(statusFilter) || s.Status == statusFilter))
+        ?? [];
+
+    protected override async Task OnInitializedAsync()
+    {
+        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments");
+    }
+
+    private void ShowCreateForm()
+    {
+        showCreate = true;
+        createError = null;
+    }
+
+    private async Task CreateShipment()
+    {
+        if (string.IsNullOrWhiteSpace(newTrackingNumber) || string.IsNullOrWhiteSpace(newOrigin) || string.IsNullOrWhiteSpace(newDestination))
+        {
+            createError = "Tracking #, Origin, and Destination are required.";
+            return;
+        }
+
+        isCreating = true;
+        createError = null;
+
+        var payload = new
+        {
+            TrackingNumber = newTrackingNumber,
+            Origin = newOrigin,
+            Destination = newDestination,
+            EstimatedDelivery = newEstimatedDelivery,
+            Notes = (string?)null,
+            CustomerId = (string?)null
+        };
+
+        var response = await Http.PostAsJsonAsync("api/shipments", payload);
+        if (response.IsSuccessStatusCode)
+        {
+            var created = await response.Content.ReadFromJsonAsync<ShipmentDto>();
+            if (created != null) shipments?.Insert(0, created);
+            showCreate = false;
+            newTrackingNumber = "";
+            newOrigin = "";
+            newDestination = "";
+            newEstimatedDelivery = null;
+        }
+        else
+        {
+            createError = $"Failed to create shipment (HTTP {(int)response.StatusCode}).";
+        }
+        isCreating = false;
+    }
+
+    private async Task UpdateStatus(ShipmentDto shipment, string? newStatus)
+    {
+        if (string.IsNullOrEmpty(newStatus) || newStatus == shipment.Status) return;
+
+        var payload = new { Status = newStatus, Notes = (string?)null };
+        var response = await Http.PutAsJsonAsync($"api/shipments/{shipment.Id}/status", payload);
+        if (response.IsSuccessStatusCode)
+        {
+            shipment.Status = newStatus;
+        }
+    }
+
+    private static string GetStatusBadgeClass(string status) => status switch
+    {
+        "Pending" => "bg-secondary",
+        "PickedUp" => "bg-info text-dark",
+        "InTransit" => "bg-primary",
+        "OutForDelivery" => "bg-warning text-dark",
+        "Delivered" => "bg-success",
+        "Exception" => "bg-danger",
+        _ => "bg-secondary"
+    };
+
+    private static string FormatStatus(string status) => status switch
+    {
+        "PickedUp" => "Picked Up",
+        "InTransit" => "In Transit",
+        "OutForDelivery" => "Out for Delivery",
+        _ => status
+    };
+}
