@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize]
@rendermode InteractiveWebAssembly

<PageTitle>Track Shipment</PageTitle>

<h3>Track Your Shipment</h3>

<div class="mb-4 d-flex gap-2">
    <input class="form-control" style="max-width:350px"
           placeholder="Enter tracking number (e.g., TRK-20260701-001)"
           @bind="trackingNumber" @onkeydown="HandleKeyDown" />
    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
        @(isLoading ? "Searching..." : "Track")
    </button>
</div>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (result != null)
{
    <div class="card" style="max-width:600px">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@result.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(result.Status)">@FormatStatus(result.Status)</span>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-4">Origin</dt>
                <dd class="col-sm-8">@result.Origin</dd>

                <dt class="col-sm-4">Destination</dt>
                <dd class="col-sm-8">@result.Destination</dd>

                <dt class="col-sm-4">Shipped On</dt>
                <dd class="col-sm-8">@result.CreatedAt.ToString("MMMM dd, yyyy")</dd>

                <dt class="col-sm-4">Estimated Delivery</dt>
                <dd class="col-sm-8">
                    @if (result.EstimatedDelivery.HasValue)
                    {
                        <span>@result.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</span>
                        @if (result.Status != "Delivered")
                        {
                            var daysLeft = (result.EstimatedDelivery.Value - DateTime.UtcNow).Days;
                            <span class="text-muted ms-2">
                                (@(daysLeft > 0 ? $"{daysLeft} days remaining" : "arriving today or overdue"))
                            </span>
                        }
                    }
                    else
                    {
                        <span class="text-muted">Not available</span>
                    }
                </dd>

                @if (!string.IsNullOrEmpty(result.Notes))
                {
                    <dt class="col-sm-4">Notes</dt>
                    <dd class="col-sm-8">@result.Notes</dd>
                }
            </dl>
        </div>
        <div class="card-footer">
            <ProgressBar Status="@result.Status" />
        </div>
    </div>
}

@code {
    [Inject] private HttpClient Http { get; set; } = default!;

    private string trackingNumber = "";
    private bool isLoading;
    private string? errorMessage;
    private ShipmentDto? result;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = null;
        result = null;

        try
        {
            var response = await Http.GetAsync($"api/shipments/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
            if (response.IsSuccessStatusCode)
            {
                result = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            }
            else if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            {
                errorMessage = "No shipment found with that tracking number.";
            }
            else
            {
                errorMessage = "An error occurred while looking up the shipment.";
            }
        }
        catch
        {
            errorMessage = "Unable to connect to the server. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info text-dark",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Exception" => "bg-danger",
        _ => "bg-secondary"
    };

    private static string FormatStatus(string status) => status switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => status
    };
}

