@namespace ShipmentTracker.Client.Pages

<div class="mt-2">
    <div class="d-flex justify-content-between mb-1">
        @foreach (var step in steps)
        {
            <small class="@(IsCompleted(step) ? "fw-bold text-success" : (IsCurrent(step) ? "fw-bold text-primary" : "text-muted"))">
                @FormatStep(step)
            </small>
        }
    </div>
    <div class="progress" style="height: 8px;">
        <div class="progress-bar @BarClass" role="progressbar"
             style="width: @ProgressPercent%"></div>
    </div>
</div>

@code {
    [Parameter] public string Status { get; set; } = "Pending";

    private static readonly string[] steps = ["Pending", "PickedUp", "InTransit", "OutForDelivery", "Delivered"];

    private int CurrentIndex => Status == "Exception" ? -1 : Array.IndexOf(steps, Status);

    private int ProgressPercent => Status == "Exception" ? 100 : (CurrentIndex >= 0 ? (int)(CurrentIndex / 4.0 * 100) : 0);

    private string BarClass => Status == "Exception" ? "bg-danger" : "bg-success";

    private bool IsCompleted(string step) => CurrentIndex >= 0 && Array.IndexOf(steps, step) < CurrentIndex;
    private bool IsCurrent(string step) => step == Status;

    private static string FormatStep(string step) => step switch
    {
        "PickedUp" => "Picked Up",
        "InTransit" => "In Transit",
        "OutForDelivery" => "Out for Delivery",
        _ => step
    };
}

